import { useId, useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { Stack, TextField, Tag, Text } from '@jinx-ui/react';

// Точный API @jinx-ui/react мне недоступен: предполагаются TextField(label,value,onChange,onKeyDown,helperText),
// Tag(onRemove), Stack(direction,gap,wrap), Text(size,tone). Имена пропсов могут потребовать правки под реальный пакет.

export type TagPickerProps = {
  label?: string;
  placeholder?: string;
  initialTags?: string[];
  maxTags?: number;
  onChange: (tags: string[]) => void;
};

const normalize = (raw: string): string => raw.trim().replace(/\s+/g, ' ');

function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  initialTags = [],
  maxTags = 10,
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');
  const listId = useId();

  const commit = (next: string[]) => {
    setTags(next);
    onChange(next);
  };

  const addTag = (raw: string) => {
    const tag = normalize(raw);
    if (!tag) return;
    if (tags.length >= maxTags) return;
    const exists = tags.some((t) => t.toLowerCase() === tag.toLowerCase());
    if (exists) return;
    commit([...tags, tag]);
  };

  const removeTag = (tag: string) => {
    commit(tags.filter((t) => t !== tag));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(draft);
      setDraft('');
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  const isFull = tags.length >= maxTags;

  return (
    <Stack direction="column" gap="var(--jx-space-2)">
      <TextField
        label={label}
        placeholder={isFull ? 'Достигнут лимит тегов' : placeholder}
        value={draft}
        disabled={isFull}
        aria-describedby={listId}
        onChange={(event: ChangeEvent<HTMLInputElement>) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => {
          addTag(draft);
          setDraft('');
        }}
        helperText={`Enter или запятая добавляют тег · ${tags.length} из ${maxTags}`}
      />

      {tags.length > 0 ? (
        <Stack id={listId} direction="row" gap="var(--jx-space-1)" wrap aria-live="polite">
          {tags.map((tag) => (
            <Tag key={tag} onRemove={() => removeTag(tag)} aria-label={`Удалить тег ${tag}`}>
              {tag}
            </Tag>
          ))}
        </Stack>
      ) : (
        <Text id={listId} size="sm" tone="muted">
          Теги пока не выбраны
        </Text>
      )}
    </Stack>
  );
}

export default TagPicker;

